import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { InspectorContextProvider } from "../InspectorContext";
import { Toaster } from "../Toaster";
import { InspectorContent } from "./InspectorContent";
import type { InspectorProps } from "./Inspector";

export type InspectorCoreProps = InspectorProps & {
  isEmbedded: boolean;
};

const queryClient = new QueryClient();

/**
 * Internal core — wires QueryClient, context, content and toaster.
 * Not exported from the package; used by Inspector and the standalone App.
 */
export const InspectorCore = ({
  track,
  logError,
  showToast,
  updateToast,
  dismissToast,
  isToastVisible,
  onboardingTooltips,
  socketReconnectAttempts,
  ...rest
}: InspectorCoreProps) => (
  <QueryClientProvider client={queryClient}>
    <InspectorContextProvider
      track={track}
      logError={logError}
      showToast={showToast}
      updateToast={updateToast}
      dismissToast={dismissToast}
      isToastVisible={isToastVisible}
      onboardingTooltips={onboardingTooltips}
      socketReconnectAttempts={socketReconnectAttempts}
    >
      <InspectorContent {...rest} />
      {!showToast && <Toaster />}
    </InspectorContextProvider>
  </QueryClientProvider>
);
